-- lovable-cron-fallback-reviewed: RSS publishers and the quote sources used here offer no push delivery; one five-minute scheduled check keeps data fresh without visitor-triggered work.
SELECT cron.unschedule(jobid) FROM cron.job WHERE jobname IN ('trackindia-news-ingest', 'trackindia-ticker-refresh', 'trackindia-market-refresh');
SELECT cron.schedule('trackindia-market-refresh', '*/5 * * * *', $$ SELECT net.http_post(url := 'https://project--cdea9cdf-8b30-4ec3-aa0a-7273c2f53d6c.lovable.app/api/public/ingest-rss', headers := '{"Content-Type":"application/json"}'::jsonb, body := '{}'::jsonb); SELECT net.http_post(url := 'https://project--cdea9cdf-8b30-4ec3-aa0a-7273c2f53d6c.lovable.app/api/public/refresh-tickers', headers := '{"Content-Type":"application/json"}'::jsonb, body := '{}'::jsonb); $$);